  inset: 0;
}

.hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity var(--duration-fade) var(--ease-standard);
}

.hero__slide--active {
  opacity: 1;
}

.hero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__slide--zoom .hero__image {
  animation: hero-zoom var(--duration-slide) var(--ease-out);
}

@keyframes hero-zoom {
  from {
    transform: scale(1.05);
  }
}

.hero__content {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-32);
}

.hero__heading {
  display: flex;
  flex-direction: column;
  gap: var(--space-16);
}

.hero__eyebrow {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
}

.hero__title {
  font-size: var(--font-size-display);
  line-height: var(--line-height-none);
}

/* Controls */
.hero__arrow {
  position: absolute;
  inset-block-end: var(--space-16);
  display: grid;
  place-items: center;
  width: var(--size-control);
  height: var(--size-control);
  background: var(--color-scrim-soft);
  border-radius: var(--radius-pill);
}

.hero__arrow--prev {
  inset-inline-start: max(var(--space-16), calc(50% - 10.125rem));
}

.hero__arrow--next {
  inset-inline-end: max(var(--space-16), calc(50% - 10.125rem));
}

.hero__progress {
  position: absolute;
  inset-block-end: calc(var(--space-16) + var(--size-control) / 2 - 1px);
  inset-inline-start: 50%;
  display: flex;
  gap: var(--space-4);
  transform: translateX(-50%);
}

.hero__bar {
  position: relative;
  width: var(--space-48);
  height: 2px;
  overflow: hidden;
  background: var(--color-track);
}

.hero__bar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__bar--active::after {
  transform: scaleX(1);
}

.js .hero__bar--active::after {
  animation: hero-progress var(--duration-slider-interval) linear both;
}

.hero--paused .hero__bar--active::after {
  animation-play-state: paused;
}

@keyframes hero-progress {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

.hero__pause {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: calc(100% + var(--space-4));
  display: grid;
  place-items: center;
  width: var(--space-32);
  height: var(--space-32);
  background: var(--color-scrim-soft);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
}

.hero__pause-icon--play,
.hero__pause[aria-pressed="true"] .hero__pause-icon--pause {
  display: none;
}

.hero__pause[aria-pressed="true"] .hero__pause-icon--play {
  display: block;
}

html:not(.js) .hero__arrow,
html:not(.js) .hero__pause {
  display: none;
}

/* Rating badge */
.hero__badge {
  position: absolute;
  inset-block-end: 5.5rem;
  inset-inline-end: var(--space-16);
  display: flex;
  align-items: center;
  gap: var(--space-12);
  padding: var(--space-12) var(--space-24);
  background: var(--color-scrim);
  border-radius: var(--radius-pill);
}

.hero__rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-title);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
}

.hero__badge-label {
  font-size: var(--font-size-small);
  line-height: var(--line-height-tight);
  white-space: nowrap;
}

@media (min-width: 48rem) {
  .hero {
    align-items: center;
    padding-block: var(--space-96);
  }

  .hero__bar {
    width: var(--space-64);
  }

  .hero__pause {
    inset-inline-start: calc(100% + var(--space-8));
  }
}

@media (min-width: 60rem) {
  .hero__badge {
    inset-block-end: var(--space-16);
  }
}

/* Side arrows and bottom offsets from Figma */
@media (min-width: 117.5rem) {
  .hero__arrow {
    inset-block-end: auto;
    inset-block-start: 50%;
    transform: translateY(-50%);
  }

  .hero__arrow--prev {
    inset-inline-start: var(--space-72);
  }

  .hero__arrow--next {
    inset-inline-end: var(--space-72);
  }

  .hero__progress {
    inset-block-end: var(--space-32);
  }

  .hero__badge {
    inset-block-end: var(--space-32);
    inset-inline-end: var(--space-72);
  }
}

