/*
 * Colors follow Figma on purpose: no gradients are added under the text,
 * so contrast over the photos is a documented WCAG exception.
 * Controls sit in a bottom row until the viewport leaves room for the side
 * arrows from Figma without covering the text (117.5rem / 1880px).
 */
.hero {
  position: relative;
  display: flex;
  align-items: flex-start;
  min-height: max(min(100svh, var(--hero-max-height)), 37.5rem);
  padding-block: 7.5rem 9rem;
  overflow: clip;
  color: var(--color-white);
}

.hero__slides {
  position: absolute;
  inset: 0;
  container-type: size;
}

/* A 16:9 box scaled like object-fit: cover, so every layer lines up with the photo */
.hero__stage {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  width: max(100cqw, 100cqh * 16 / 9);
  aspect-ratio: 16 / 9;
  transform: translate(-50%, -50%);
}

.hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity var(--duration-fade) var(--ease-standard);
}

.hero__slide--active {
  opacity: 1;
}

.hero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__slide--zoom .hero__image {
  animation: hero-zoom var(--duration-slide) var(--ease-out);
}

@keyframes hero-zoom {
  from {
    transform: scale(1.05);
  }
}

.hero__content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-32);
  pointer-events: none; /* Lets clicks reach the lamps under the empty part of the row */
}

.hero__content a {
  pointer-events: auto;
}

.hero__heading {
  display: flex;
  flex-direction: column;
  gap: var(--space-16);
}

.hero__eyebrow {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
}

.hero__title {
  font-size: var(--font-size-display);
  line-height: var(--line-height-none);
}

/* Lights: only opacity changes, so nothing repaints during the animation */
.hero__dim {
  position: absolute;
  inset: 0;
  background: var(--color-ink);
  opacity: 0;
  transition: opacity var(--duration-light) var(--ease-standard);
}

.hero--lit .hero__dim {
  opacity: 0.72;
}

.hero__lamp {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero__lamp-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity var(--duration-light) var(--ease-standard);
}

.hero--lit .hero__lamp-image {
  opacity: 1;
}

.hero__lamp--top .hero__lamp-image {
  clip-path: polygon(39.5% 9%, 59.5% 9%, 59.5% 45.4%, 39.5% 45.4%);
}

.hero__lamp--left .hero__lamp-image {
  clip-path: polygon(22% 40.8%, 43.5% 40.8%, 43.5% 76.4%, 22% 76.4%);
}

.hero__lamp--right .hero__lamp-image {
  clip-path: polygon(60.4% 31%, 79.7% 31%, 79.7% 70%, 55.9% 70%, 55.9% 57.4%);
}

.hero__beam,
.hero__glow {
  position: absolute;
  inset-block-start: var(--lens-y);
  inset-inline-start: var(--lens-x);
  opacity: 0;
  transition: opacity var(--duration-fade) var(--ease-standard);
}

.hero__beam {
  width: 55%;
  aspect-ratio: 1;
  background: conic-gradient(from 138deg at 50% 0, transparent, var(--color-light) 42deg, transparent 84deg);
  mask-image: radial-gradient(circle at 50% 0, #000, transparent 70%);
  transform: translateX(-50%) rotate(var(--beam-angle));
  transform-origin: 50% 0;
}

.hero__glow {
  width: 14%;
  aspect-ratio: 1;
  background: radial-gradient(circle, var(--color-light-core), var(--color-light) 35%, transparent 70%);
  transform: translate(-50%, -50%);
}

.hero__lamp--lit .hero__beam,
.hero__lamp--lit .hero__glow {
  opacity: 1;
}

@media (prefers-reduced-motion: no-preference) {
  .hero__lamp--lit .hero__beam,
  .hero__lamp--lit .hero__glow {
    animation: hero-flicker var(--duration-light) var(--ease-standard);
  }
}

/* Two short flashes, well under the WCAG limit of three per second */
@keyframes hero-flicker {
  0% {
    opacity: 0;
  }

  25% {
    opacity: 0.8;
  }

  40% {
    opacity: 0.2;
  }

  65% {
    opacity: 1;
  }

  80% {
    opacity: 0.6;
  }
}

.hero__lamp--top {
  --lens-x: 50.9%;
  --lens-y: 32.6%;
  --beam-angle: -25deg;
}

.hero__lamp--left {
  --lens-x: 35.1%;
  --lens-y: 63.6%;
  --beam-angle: -25deg;
}

.hero__lamp--right {
  --lens-x: 60.9%;
  --lens-y: 62.2%;
  --beam-angle: 25deg;
}

.hero__lamp-button {
  position: absolute;
  border-radius: var(--radius-pill);
  pointer-events: auto;
}

.hero__lamp--top .hero__lamp-button {
  inset: 10% 41% 55.5% 40%;
}

.hero__lamp--left .hero__lamp-button {
  inset: 41% 56.8% 24.5% 22.6%;
}

.hero__lamp--right .hero__lamp-button {
  inset: 31.3% 20.6% 30.7% 56.6%;
}

html:not(.js) .hero__lamp,
html:not(.js) .hero__switch {
  display: none;
}

/* Light switch, ribbed like the lamps */
.hero__switch {
  position: absolute;
  inset-block-end: 5.5rem;
  inset-inline-start: var(--container-gutter);
  width: 5.25rem;
  height: var(--size-control);
  padding: var(--space-4);
  background: var(--color-switch);
  border: 1px solid var(--color-white);
  border-radius: var(--radius-pill);
}

.hero__switch-knob {
  display: block;
  width: 2.375rem;
  height: 100%;
  background: repeating-linear-gradient(90deg, var(--color-switch-rib) 0 0.1875rem, var(--color-switch-rib-shade) 0.1875rem 0.3125rem);
  border-radius: var(--radius-pill);
  transition: transform var(--duration-hover) var(--ease-standard);
}

.hero__switch-led {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: var(--space-14);
  width: var(--space-8);
  height: var(--space-8);
  background: var(--color-ink);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
}

.hero__switch[aria-checked="true"] .hero__switch-knob {
  transform: translateX(2.25rem);
}

.hero__switch[aria-checked="true"] .hero__switch-led {
  inset-inline: var(--space-14) auto;
  background: var(--color-accent);
}

/* Controls */
.hero__arrow {
  position: absolute;
  inset-block-end: var(--space-16);
  display: grid;
  place-items: center;
  width: var(--size-control);
  height: var(--size-control);
  background: var(--color-scrim-soft);
  border-radius: var(--radius-pill);
}

.hero__arrow--prev {
  inset-inline-start: max(var(--space-16), calc(50% - 10.125rem));
}

.hero__arrow--next {
  inset-inline-end: max(var(--space-16), calc(50% - 10.125rem));
}

.hero__progress {
  position: absolute;
  inset-block-end: calc(var(--space-16) + var(--size-control) / 2 - 1px);
  inset-inline-start: 50%;
  display: flex;
  gap: var(--space-4);
  transform: translateX(-50%);
}

.hero__bar {
  position: relative;
  width: var(--space-48);
  height: 2px;
  overflow: hidden;
  background: var(--color-track);
}

.hero__bar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__bar--active::after {
  transform: scaleX(1);
}

.js .hero__bar--active::after {
  animation: hero-progress var(--duration-slider-interval) linear both;
}

.hero--paused .hero__bar--active::after {
  animation-play-state: paused;
}

@keyframes hero-progress {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

.hero__pause {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: calc(100% + var(--space-4));
  display: grid;
  place-items: center;
  width: var(--space-32);
  height: var(--space-32);
  background: var(--color-scrim-soft);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
}

.hero__pause-icon--play,
.hero--stopped .hero__pause-icon--pause {
  display: none;
}

.hero--stopped .hero__pause-icon--play {
  display: block;
}

html:not(.js) .hero__arrow,
html:not(.js) .hero__pause {
  display: none;
}

/* Rating badge */
.hero__badge {
  position: absolute;
  inset-block-end: 5.5rem;
  inset-inline-end: var(--space-16);
  display: flex;
  align-items: center;
  gap: var(--space-12);
  padding: var(--space-12) var(--space-24);
  background: var(--color-scrim);
  border-radius: var(--radius-pill);
}

.hero__rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-title);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
}

/* Below 1024px the badge shows only the rating, the label stays for screen readers */
.hero__badge-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  font-size: var(--font-size-small);
  line-height: var(--line-height-tight);
  white-space: nowrap;
}

@media (min-width: 48rem) {
  .hero {
    align-items: center;
    padding-block: var(--space-96);
  }

  .hero__bar {
    width: var(--space-64);
  }

  .hero__pause {
    inset-inline-start: calc(100% + var(--space-8));
  }
}

@media (min-width: 60rem) {
  .hero__badge,
  .hero__switch {
    inset-block-end: var(--space-16);
  }
}

@media (min-width: 64rem) {
  .hero__badge-label {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    clip-path: none;
  }
}

/* Side arrows and bottom offsets from Figma */
@media (min-width: 117.5rem) {
  .hero__arrow {
    inset-block-end: auto;
    inset-block-start: 50%;
    transform: translateY(-50%);
  }

  .hero__arrow--prev {
    inset-inline-start: var(--space-72);
  }

  .hero__arrow--next {
    inset-inline-end: var(--space-72);
  }

  .hero__progress {
    inset-block-end: var(--space-32);
  }

  .hero__badge {
    inset-block-end: var(--space-32);
    inset-inline-end: var(--space-72);
  }

  .hero__switch {
    inset-block-end: var(--space-32);
    inset-inline-start: calc((100% - var(--container-max)) / 2);
  }
}

// Marks JS availability so CSS can enhance without hiding content from no-JS users.
document.documentElement.classList.add('js');

const DESKTOP_QUERY = '(min-width: 75rem)';

function initHeader() {
  const header = document.querySelector('.header');
  if (!header) return;

  const toggle = header.querySelector('.header__toggle');
  const panel = header.querySelector('.header__panel');
  const items = [...header.querySelectorAll('.nav__item:has(.nav__trigger)')];
  const desktop = window.matchMedia(DESKTOP_QUERY);
  let openedByHover = null;

  const openItem = () => items.find((item) => item.classList.contains('nav__item--open'));

  const syncHeaderState = () => {
    const isPanelOpen = toggle.getAttribute('aria-expanded') === 'true';
    header.classList.toggle('header--active', isPanelOpen || Boolean(openItem()));
  };

  const setItem = (item, isOpen) => {
    item.classList.toggle('nav__item--open', isOpen);
    item.querySelector('.nav__trigger').setAttribute('aria-expanded', String(isOpen));
    syncHeaderState();
  };

  const closeItems = () => items.forEach((item) => setItem(item, false));

  const setPanel = (isOpen) => {
    toggle.setAttribute('aria-expanded', String(isOpen));
    toggle.setAttribute('aria-label', isOpen ? 'Zamknij menu' : 'Otwórz menu');
    panel.classList.toggle('header__panel--open', isOpen);
    if (!isOpen) closeItems();
    syncHeaderState();
  };

  toggle.addEventListener('click', () => {
    setPanel(toggle.getAttribute('aria-expanded') !== 'true');
  });

  items.forEach((item) => {
    const trigger = item.querySelector('.nav__trigger');

    trigger.addEventListener('click', () => {
      // A click on a dropdown opened by hover keeps it open instead of toggling it.
      if (openedByHover === item) {
        openedByHover = null;
        return;
      }
      const shouldOpen = !item.classList.contains('nav__item--open');
      if (desktop.matches) closeItems();
      setItem(item, shouldOpen);
    });

    item.addEventListener('pointerenter', (event) => {
      if (!desktop.matches || event.pointerType !== 'mouse') return;
      closeItems();
      setItem(item, true);
      openedByHover = item;
    });

    item.addEventListener('pointerleave', (event) => {
      if (!desktop.matches || event.pointerType !== 'mouse') return;
      openedByHover = null;
      if (!item.contains(document.activeElement)) setItem(item, false);
    });

    item.addEventListener('focusout', (event) => {
      if (desktop.matches && !item.contains(event.relatedTarget)) setItem(item, false);
    });
  });

  document.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;

    const item = openItem();
    if (item) {
      setItem(item, false);
      item.querySelector('.nav__trigger').focus();
    } else if (toggle.getAttribute('aria-expanded') === 'true') {
      setPanel(false);
      toggle.focus();
    }
  });

  document.addEventListener('click', (event) => {
    if (desktop.matches && !header.contains(event.target)) closeItems();
  });

  desktop.addEventListener('change', () => setPanel(false));
}

function initHero() {
  const hero = document.querySelector('.hero');
  if (!hero) return;

  const slides = [...hero.querySelectorAll('.hero__slide')];
  const bars = [...hero.querySelectorAll('.hero__bar')];
  const pauseButton = hero.querySelector('.hero__pause');
  const lightSwitch = hero.querySelector('.hero__switch');
  const lamps = [...hero.querySelectorAll('.hero__lamp')];
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  // Temporary holds (focus, hover on controls) never override the user's pause choice.
  const holds = new Set();
  let current = 0;
  let isUserPaused = reducedMotion.matches;

  const syncPaused = () => {
    hero.classList.toggle('hero--paused', isUserPaused || holds.size > 0);
    hero.classList.toggle('hero--stopped', isUserPaused);
    pauseButton.setAttribute(
      'aria-label',
      isUserPaused ? 'Wznów automatyczną zmianę slajdów' : 'Zatrzymaj automatyczną zmianę slajdów',
    );
  };

  const isLit = (lamp) => lamp.classList.contains('hero__lamp--lit');

  const setLamp = (lamp, isOn) => {
    lamp.classList.toggle('hero__lamp--lit', isOn);
    lamp.querySelector('.hero__lamp-button').setAttribute('aria-pressed', String(isOn));
  };

  const syncLights = () => {
    const anyLit = lamps.some(isLit);
    hero.classList.toggle('hero--lit', anyLit);
    lightSwitch.setAttribute('aria-checked', String(anyLit));
    lightSwitch.setAttribute('aria-label', anyLit ? 'Zgaś lampy' : 'Zapal lampy');
    if (anyLit) holds.add('lights');
    else holds.delete('lights');
    syncPaused();
  };

  const showSlide = (index) => {
    const next = (index + slides.length) % slides.length;

    lamps.forEach((lamp) => setLamp(lamp, false));
    syncLights();

    slides.forEach((slide, slideIndex) => {
      const isActive = slideIndex === next;
      slide.classList.toggle('hero__slide--active', isActive);
      slide.classList.toggle('hero__slide--zoom', isActive);
      if (isActive) slide.removeAttribute('aria-hidden');
      else slide.setAttribute('aria-hidden', 'true');
    });
    bars.forEach((bar, barIndex) => {
      bar.classList.toggle('hero__bar--active', barIndex === next);
    });

    current = next;
  };

  hero.querySelector('.hero__arrow--prev').addEventListener('click', () => showSlide(current - 1));
  hero.querySelector('.hero__arrow--next').addEventListener('click', () => showSlide(current + 1));

  // Lamps exist only on the first slide, so using them from another slide returns to it.
  const showLampSlide = () => {
    if (current !== 0) showSlide(0);
  };

  lightSwitch.addEventListener('click', () => {
    const shouldLight = !lamps.some(isLit);
    if (shouldLight) showLampSlide();
    lamps.forEach((lamp) => setLamp(lamp, shouldLight));
    syncLights();
  });

  lamps.forEach((lamp) => {
    lamp.querySelector('.hero__lamp-button').addEventListener('click', () => {
      showLampSlide();
      setLamp(lamp, !isLit(lamp));
      syncLights();
    });
  });

  pauseButton.addEventListener('click', () => {
    isUserPaused = !isUserPaused;
    syncPaused();
  });

  // The progress animation is the autoplay timer, so the bar and the slide stay in sync.
  bars.forEach((bar) => {
    bar.addEventListener('animationend', () => showSlide(current + 1));
  });

  hero.addEventListener('focusin', (event) => {
    if (!event.target.matches(':focus-visible')) return;
    holds.add('focus');
    syncPaused();
  });

  hero.addEventListener('focusout', (event) => {
    if (hero.contains(event.relatedTarget)) return;
    holds.delete('focus');
    syncPaused();
  });

  // Holding on the whole section would stop autoplay under a resting cursor.
  hero.querySelectorAll('a, button').forEach((control) => {
    control.addEventListener('pointerenter', (event) => {
      if (event.pointerType !== 'mouse') return;
      holds.add('hover');
      syncPaused();
    });

    control.addEventListener('pointerleave', () => {
      holds.delete('hover');
      syncPaused();
    });
  });

  syncPaused();
}

