/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body,
h1,
h2,
h3,
p,
ul,
ol,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img,
svg,
picture {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Keeps the hidden attribute working over the display rules above */
[hidden] {
  display: none;
}

/* Base typography */
body {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  font-size-adjust: from-font;
  font-weight: var(--font-weight-medium);
  line-height: var(--line-height-base);
  color: var(--color-text);
  background: var(--color-white);
  overflow-wrap: break-word;
}

h1,
h2,
h3 {
  font-size: inherit;
  font-weight: var(--font-weight-bold);
  text-wrap: balance;
}

/* Two-tone ring stays visible on light, dark and photo backgrounds */
:focus-visible {
  outline: var(--focus-width) solid var(--focus-color);
  outline-offset: var(--focus-offset);
  box-shadow: 0 0 0 calc(var(--focus-offset) + var(--focus-width)) var(--focus-halo);
}

/* Layout */
.container {
  width: 100%;
  max-width: calc(var(--container-max) + 2 * var(--container-gutter));
  margin-inline: auto;
  padding-inline: var(--container-gutter);
}

/* Buttons */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-16) var(--space-24);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-base);
  text-align: center;
  white-space: nowrap;
  border-radius: var(--radius-pill);
  transition: transform var(--duration-fast) var(--ease-standard);
}

/* Hover is an assumption, Figma has no state for this button */
.button--accent {
  color: var(--color-text);
  background: var(--color-accent);
}

.button--accent:hover {
  transform: translateY(calc(-1 * var(--space-2)));
}

/* Accessibility helpers */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: var(--space-8);
  left: var(--space-8);
  z-index: 100;
  padding: var(--space-12) var(--space-24);
  font-weight: var(--font-weight-bold);
  color: var(--color-white);
  background: var(--color-ink);
  border-radius: var(--radius-pill);
  transform: translateY(calc(-100% - var(--space-16)));
  transition: transform var(--duration-hover) var(--ease-standard);
}

.skip-link:focus-visible {
  transform: none;
}

/*
 * Design tokens from Figma (frame 1:505, guidelines frame 16:91).
 * Figma has no variables, so values are read from layers.
 *
 * Breakpoints (assumption, Figma has desktop only). Custom properties do not
 * work in media queries, so use these values directly with min-width:
 *   tablet:  48rem (768px)
 *   desktop: 75rem (1200px)
 */

:root {
  /* Colors */
  --color-accent: #f2bf25;
  --color-ink: #101011;
  --color-text: #1e1e1e;
  --color-white: #fff;
  --color-border: #e7e7e7;
  --color-button-hover: #4a4a4a;
  --color-track: rgb(231 231 231 / 50%);
  --color-scrim-soft: rgb(16 16 17 / 20%);
  --color-scrim: rgb(16 16 17 / 40%);
  --color-tile-configurator: #72a3f3;
  --color-tile-catalog: #fdf8eb;
  --color-tile-smart: #e8e4df;

  /* Hero lights (assumption, not in Figma; olive and sand come from the lamps) */
  --color-light: rgb(242 191 37 / 50%);
  --color-light-core: rgb(255 240 200 / 95%);
  --color-switch: #56663e;
  --color-switch-rib: #e9d1b4;
  --color-switch-rib-shade: #b49f82;

  /* Typography */
  --font-family-base: "Red Hat Display", system-ui, sans-serif;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  --font-size-caption: 0.75rem; /* 12px */
  --font-size-small: 0.8125rem; /* 13px */
  --font-size-body: 0.875rem; /* 14px */
  --font-size-base: 1rem; /* 16px */
  --font-size-title: 1.3125rem; /* 21px */
  --font-size-heading: clamp(1.5rem, 1.318rem + 0.91vw, 2rem); /* 24-32px */
  --font-size-display: clamp(2.25rem, 1.795rem + 2.27vw, 3.5rem); /* 36-56px */

  --line-height-none: 1;
  --line-height-tight: 1.1;
  --line-height-base: 1.2;

  /* Spacing */
  --space-2: 0.125rem;
  --space-3: 0.1875rem;
  --space-4: 0.25rem;
  --space-8: 0.5rem;
  --space-9: 0.5625rem;
  --space-11: 0.6875rem;
  --space-12: 0.75rem;
  --space-14: 0.875rem;
  --space-16: 1rem;
  --space-24: 1.5rem;
  --space-32: 2rem;
  --space-48: 3rem;
  --space-64: 4rem;
  --space-72: 4.5rem;
  --space-86: 5.375rem;
  --space-96: 6rem;

  /* Radii */
  --radius-xs: 0.125rem;
  --radius-sm: 0.25rem;
  --radius-lg: 1.5rem;
  --radius-pill: 6.25rem;

  /* Sizes */
  --size-control: 3rem; /* 48px circle buttons */
  --size-icon-sm: 1rem;
  --size-icon-md: 1.25rem;
  --size-icon-lg: 1.5rem;
  --size-icon-xl: 2rem;

  /* Layout */
  --container-max: 100rem; /* 1600px */
  --container-gutter: var(--space-16);
  --hero-max-height: 67.5rem; /* 1080px */
  --tile-height: 32.375rem; /* 518px */

  /* Motion */
  --duration-fast: 200ms;
  --duration-hover: 250ms;
  --duration-zoom: 500ms;
  --duration-fade: 600ms;
  --duration-slide: 800ms;
  --duration-light: 700ms;
  --duration-slider-interval: 3s;
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-out: ease-out;

  /* Focus (WCAG 2.4.7, assumption, not in Figma) */
  --focus-width: 2px;
  --focus-offset: 2px;
  --focus-color: var(--color-ink);
  --focus-halo: var(--color-white);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 1ms;
    --duration-hover: 1ms;
    --duration-zoom: 1ms;
    --duration-fade: 1ms;
    --duration-slide: 1ms;
    --duration-light: 1ms;
  }
}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

