/*
 * Figma has desktop only: the single column below 75rem is an assumption.
 * The mockup art is flattened on the tile color, so it blends with the tile
 * and scales as one image.
 */
.promo-grid {
  padding-block: var(--space-64) var(--section-padding);
}

.promo-grid__list {
  display: grid;
  gap: var(--space-16);
}

.tile {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: var(--tile-height);
  overflow: hidden;
  color: var(--color-ink);
  border-radius: var(--radius-lg);
}

.tile--thoro,
.tile--configurator {
  color: var(--color-white);
}

.tile--configurator {
  --art-width: 32.25rem;

  background: var(--color-tile-configurator);
}

.tile--catalog {
  --art-width: 31rem;

  background: var(--color-tile-catalog);
}

.tile--smart {
  --art-width: 36.125rem;

  background: var(--color-tile-smart);
}

.tile__image {
  position: absolute;
  inset-block-start: 0;
  inset-inline-end: 0;
  z-index: -1;
  width: min(100%, var(--art-width));
  transition: transform var(--duration-zoom) var(--ease-out);
}

.tile--thoro .tile__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tile__content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-24);
  padding: var(--tile-padding);
}

.tile__heading {
  display: flex;
  flex-direction: column;
  gap: var(--space-12);
  max-width: 25rem;
}

.tile__eyebrow {
  font-size: var(--font-size-title);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
}

.tile__title {
  font-size: var(--font-size-heading);
  line-height: var(--line-height-tight);
}

/* The link covers the whole tile, so hover and click share one area */
.tile__link::after {
  content: "";
  position: absolute;
  inset: 0;
}

@media (hover: hover) {
  .tile:hover .tile__image {
    transform: scale(1.1);
  }

  .tile:hover .tile__link {
    background: var(--color-button-hover);
  }
}

.tile:has(:focus-visible) .tile__image {
  transform: scale(1.1);
}

.tile:has(:focus-visible) .tile__link {
  background: var(--color-button-hover);
}

@media (min-width: 75rem) {
