/*
 * Figma holds this section as a raster, so type sizes are estimated from it.
 * The gradient is the fallback for no JS, no WebGL and a lost GL context.
 */
.shader-cta {
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  min-height: max(30rem, 43.5vw); /* 835 / 1920 from Figma */
