    var(--color-ink);
}

.shader-cta__canvas {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity var(--duration-fade) var(--ease-standard);
}

.shader-cta--ready .shader-cta__canvas {
  opacity: 1;
}

.shader-cta__content {
  display: flex;
