.shader-cta__action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-16);
}

.shader-cta__note {
  max-width: 15rem;
  font-size: var(--font-size-body);
  line-height: var(--line-height-base);
  text-wrap: balance;
}

/* Shown only when there is an animation to stop */
.shader-cta__pause {
  position: absolute;
  inset-block-end: var(--space-16);
  inset-inline-end: var(--space-16);
  display: none;
  place-items: center;
  width: var(--size-control);
  height: var(--size-control);
  background: var(--color-scrim-soft);
  border-radius: var(--radius-pill);
}

.shader-cta--ready .shader-cta__pause {
  display: grid;
}

.shader-cta__icon--play,
.shader-cta--stopped .shader-cta__icon--pause {
  display: none;
}

.shader-cta--stopped .shader-cta__icon--play {
  display: block;
}
