// Every time-based term uses a whole multiple of uPhase, so the last frame of the
// loop equals the first one and there is no visible cut.
const LOOP_DURATION = 24000;

// Soft beams need no sharpness, so half resolution keeps the GPU load low.
const RENDER_SCALE = 0.5;
const MAX_PIXEL_RATIO = 1.5;

const VERTEX_SHADER = `
  attribute vec2 position;

  void main() {
    gl_Position = vec4(position, 0.0, 1.0);
  }
`;

const FRAGMENT_SHADER = `
  precision mediump float;

  uniform vec2 uResolution;
  uniform float uPhase;

  const vec3 INK = vec3(16.0, 16.0, 17.0) / 255.0;
  const vec3 GOLD = vec3(242.0, 191.0, 37.0) / 255.0;

  float beams(vec2 point, float angle, float density, float offset) {
    float wave = dot(point, vec2(cos(angle), sin(angle))) * density;
    wave += 0.45 * sin(point.y * 2.3 + uPhase + offset);
    wave += 0.25 * sin(point.x * 3.1 - 2.0 * uPhase + offset * 2.0);
    float beam = 0.5 + 0.5 * sin(wave + 1.1 * sin(uPhase + offset));
    return beam * beam;
  }

  // Breaks up colour banding in the long dark gradients.
  float dither(vec2 pixel) {
    return fract(sin(dot(pixel, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  }

  void main() {
    vec2 uv = gl_FragCoord.xy / uResolution;
    vec2 point = vec2(uv.x * uResolution.x / uResolution.y, uv.y);
    float light = 0.15 + beams(point, 0.66, 6.5, 0.0) + 0.6 * beams(point, 0.9, 4.2, 1.7);
    float fade = 1.0 - smoothstep(0.0, 0.72, uv.y);
    // Exponential roll-off keeps the brightest beams soft instead of clipping to flat gold.
    vec3 color = mix(INK, GOLD, 1.0 - exp(-2.2 * light * fade));
    gl_FragColor = vec4(color + dither(gl_FragCoord.xy) / 255.0, 1.0);
  }
`;

function compile(gl, type, source) {
  const shader = gl.createShader(type);
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  return shader;
}

function createProgram(gl) {
  const program = gl.createProgram();
  gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERTEX_SHADER));
  gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;

  gl.useProgram(program);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  // One triangle larger than the viewport covers the whole canvas.
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, 'position');
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  return {
    resolution: gl.getUniformLocation(program, 'uResolution'),
    phase: gl.getUniformLocation(program, 'uPhase'),
  };
}

export function initShaderCta(section) {
  const canvas = section.querySelector('.shader-cta__canvas');
  const pauseButton = section.querySelector('.shader-cta__pause');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const gl = canvas.getContext('webgl', {
    alpha: false,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'low-power',
  });
  if (!gl) return;

  let uniforms = createProgram(gl);
  if (!uniforms) return;

  let isUserPaused = reducedMotion.matches;
  let isOnScreen = true;
  let elapsed = 0;
  let previousTime = null;
  let frame = null;

  const draw = () => {
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.uniform2f(uniforms.resolution, canvas.width, canvas.height);
    gl.uniform1f(uniforms.phase, (elapsed / LOOP_DURATION) * Math.PI * 2);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  const tick = (time) => {
    elapsed = (elapsed + time - (previousTime ?? time)) % LOOP_DURATION;
    previousTime = time;
    draw();
    frame = requestAnimationFrame(tick);
  };

  const syncPlayback = () => {
    const shouldRun = !isUserPaused && isOnScreen && !document.hidden && uniforms;
    if (shouldRun && frame === null) {
      previousTime = null;
      frame = requestAnimationFrame(tick);
    } else if (!shouldRun && frame !== null) {
      cancelAnimationFrame(frame);
      frame = null;
    }
  };

  const syncPauseButton = () => {
    section.classList.toggle('shader-cta--stopped', isUserPaused);
    pauseButton.setAttribute('aria-label', isUserPaused ? 'Wznów animację tła' : 'Zatrzymaj animację tła');
  };

  const resize = () => {
    const scale = Math.min(window.devicePixelRatio, MAX_PIXEL_RATIO) * RENDER_SCALE;
    canvas.width = Math.max(1, Math.round(canvas.clientWidth * scale));
    canvas.height = Math.max(1, Math.round(canvas.clientHeight * scale));
    if (uniforms) draw();
  };

  pauseButton.addEventListener('click', () => {
    isUserPaused = !isUserPaused;
    syncPauseButton();
    syncPlayback();
  });

  reducedMotion.addEventListener('change', () => {
    isUserPaused = reducedMotion.matches;
    syncPauseButton();
    syncPlayback();
  });

  document.addEventListener('visibilitychange', syncPlayback);

  new IntersectionObserver(([entry]) => {
    isOnScreen = entry.isIntersecting;
    syncPlayback();
  }).observe(section);

  new ResizeObserver(resize).observe(canvas);

  // A lost context shows the CSS fallback until the browser restores it.
  canvas.addEventListener('webglcontextlost', (event) => {
    event.preventDefault();
    uniforms = null;
    section.classList.remove('shader-cta--ready');
    syncPlayback();
  });

  canvas.addEventListener('webglcontextrestored', () => {
    uniforms = createProgram(gl);
    if (!uniforms) return;
    resize();
    section.classList.add('shader-cta--ready');
    syncPlayback();
  });

  resize();
  syncPauseButton();
  section.classList.add('shader-cta--ready');
  syncPlayback();
}

