.footer__social-link:hover img,
.footer__flag:hover img {
  transform: scale(1.1);
}

.footer__nav {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-40) var(--space-24);
}

.footer__group {
  display: flex;
  flex-direction: column;
  gap: var(--space-24);
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-14);
}

/* Bottom: payments, awards and shops */
.footer__bottom {
  padding-block-end: var(--space-16);
}

.footer__panel {
  display: flex;
  flex-direction: column;
  gap: var(--space-24);
  padding-block: var(--space-32);
  border-block-start: 1px solid var(--color-border);
}

.footer__badges {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-8);
  max-width: 19.8125rem; /* 317px: five badges per row */
}

.footer__badge {
  padding: 0.375rem 0.4375rem; /* 6px 7px */
  overflow: clip;
  border-radius: var(--radius-4);
}

.footer__awards {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  max-width: 18.375rem; /* 294px: three awards per row */
}

.footer__flags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-8);
}

.footer__flag {
  width: var(--space-32);
  height: var(--space-32);
}

/* Caption: VAT note, partner logos and contact */
.footer__caption {
  display: flex;
  flex-direction: column;
  gap: var(--space-8);
  padding-block: var(--space-32);
  font-size: var(--font-size-caption);
}

.footer__vat {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-16);
}

.footer__partners {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.footer__partners img:last-child {
  border-radius: var(--space-2);
}

.footer__contact {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-8) var(--space-24);
  font-style: normal;
}

.footer__phone {
  display: flex;
  gap: var(--space-16);
}

@media (min-width: 48rem) {
  .footer__nav {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .footer__vat {
    flex-direction: row;
    align-items: center;
    gap: var(--space-32);
  }

  /* Divider between the note and the logos */
  .footer__vat-text {
    display: flex;
    flex: 1;
    align-items: center;
    gap: var(--space-32);
  }

  .footer__vat-text::after {
    content: "";
    flex: 1;
    border-block-start: 1px solid var(--color-border);
  }
}

@media (min-width: 75rem) {
  .footer__top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
  }

  .footer__nav {
    display: flex;
    gap: var(--footer-nav-gap);
  }

  .footer__bottom {
    display: flex;
    gap: var(--space-32);
    border-block-start: 1px solid var(--color-border);
  }

  .footer__panel {
    flex: 1;
    min-width: 0;
    border-block-start: 0;
  }

  .footer__panel:not(:last-child) {
    padding-inline-end: var(--space-32);
    border-inline-end: 1px solid var(--color-border);
  }
}
EOF
