  await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 800) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 120)); } window.scrollTo(0, 0); });
  await page.waitForTimeout(800);
  const sp = '/private/tmp/claude-501/-Users-admin-Desktop-Front-End-workspace-idmods-zadanie-rekrutacyjne/5d976ac4-c8ad-4d31-a8cb-3c2fc1cdd4f2/scratchpad/figma/local-1920.png';
  await page.screenshot({ path: sp, fullPage: true });
  return await page.evaluate(() => {
    const r = s => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return [Math.round(b.x), Math.round(b.y + scrollY), Math.round(b.width), Math.round(b.height)]; };
    return { total: document.documentElement.scrollHeight, header: r('header'), hero: r('.hero'), sections: [...document.querySelectorAll('main > section')].map(s => [s.className.split(' ')[0], ...r('.' + s.className.split(' ')[0])]), footer: r('footer') };
  });
}

