const img = new Image(); img.src = '/assets/images/hero-lamps-1920.webp'; await img.decode();
const c = document.createElement('canvas'); c.width = 1920; c.height = 1080; const x = c.getContext('2d'); x.drawImage(img, 0, 0);
const d = x.getImageData(0, 0, 1920, 1080).data;
const px = (i, j) => { const k = (j * 1920 + i) * 4; return [d[k], d[k+1], d[k+2], d[k+3]]; };
const out = {};
for (const [name, cx, cy] of [['top', 975, 367], ['left', 674, 707], ['right', 1167, 670]]) {
  // sample a profile along 4 rays to inspect colors
  out[name] = [0, 90, 180, 270].map(a => { const r = []; for (let t = 0; t < 130; t += 6) { const i = Math.round(cx + t * Math.cos(a * Math.PI / 180)), j = Math.round(cy + t * Math.sin(a * Math.PI / 180)); r.push(px(i, j).slice(0, 3).join(',')); } return a + ': ' + r.join(' | '); });
