const img = new Image(); img.src = '/assets/images/hero-lamps-1920.webp'; await img.decode();
const c = document.createElement('canvas'); c.width = 1920; c.height = 1080; const x = c.getContext('2d'); x.drawImage(img, 0, 0);
const d = x.getImageData(0, 0, 1920, 1080).data;
const px = (i, j) => { const k = (j * 1920 + i) * 4; return [d[k], d[k+1], d[k+2]]; };
const res = {};
for (const [name, cx, cy] of [['top', 975, 367], ['left', 674, 707], ['right', 1167, 670]]) {
  // reference = mean color in 9px box
  let ref = [0,0,0]; for (let a=-4;a<=4;a++) for (let b=-4;b<=4;b++){ const p=px(cx+a,cy+b); ref=ref.map((v,i)=>v+p[i]/81); }
  const N = 144, radii = [];
  for (let n = 0; n < N; n++) {
    const ang = n / N * 2 * Math.PI; let r = 4;
    for (; r < 200; r += 0.5) {
      const p = px(Math.round(cx + r * Math.cos(ang)), Math.round(cy + r * Math.sin(ang)));
      if (Math.abs(p[0]-ref[0]) + Math.abs(p[1]-ref[1]) + Math.abs(p[2]-ref[2]) > 70) break;
    }
    radii.push(r);
  }
  // median smoothing over 7 neighbours to drop outliers
  const sm = radii.map((_, i) => { const w = []; for (let k = -3; k <= 3; k++) w.push(radii[(i + k + N) % N]); return w.sort((a, b) => a - b)[3]; });
  res[name] = { ref: ref.map(Math.round), min: Math.min(...sm), max: Math.max(...sm), pts: sm.map((r, i) => { const a = i / N * 2 * Math.PI; return [+(cx + r * Math.cos(a)).toFixed(1), +(cy + r * Math.sin(a)).toFixed(1)]; }) };
}
window.__lens = res;
Object.fromEntries(Object.entries(res).map(([k, v]) => [k, [v.ref, v.min, v.max]]))

