const img = new Image(); img.src = '/assets/images/hero-lamps-1920.webp'; await img.decode();
const dbg = document.createElement('canvas'); dbg.width = 720; dbg.height = 240; dbg.id='dbg';
Object.assign(dbg.style,{position:'fixed',top:'0',left:'0',zIndex:9999,width:'720px',height:'240px',background:'#fff'});
const g = dbg.getContext('2d');
[['top',975,367],['left',674,707],['right',1167,670]].forEach(([n,cx,cy],i)=>{
  g.save(); g.translate(i*240,0); g.drawImage(img,cx-120,cy-120,240,240,0,0,240,240);
  g.strokeStyle='#0f0'; g.lineWidth=1; g.beginPath();
  window.__lens[n].pts.forEach(([x,y],k)=>{ const X=x-cx+120, Y=y-cy+120; k?g.lineTo(X,Y):g.moveTo(X,Y); }); g.closePath(); g.stroke(); g.restore();
});
document.body.append(dbg); window.scrollTo(0,0); 'ok'

