const img = new Image(); img.src = '/assets/images/hero-lamps-1920.webp'; await img.decode();
const c = document.createElement('canvas'); c.width = 1920; c.height = 1080; const x = c.getContext('2d'); x.drawImage(img, 0, 0);
const d = x.getImageData(0, 0, 1920, 1080).data;
const px = (i, j) => { const k = (j * 1920 + i) * 4; return [d[k], d[k+1], d[k+2]]; };
const trace = (cx, cy, th) => { let ref=[0,0,0]; for (let a=-4;a<=4;a++) for (let b=-4;b<=4;b++){ const p=px(cx+a,cy+b); ref=ref.map((v,i)=>v+p[i]/81); }
  const N=144, radii=[]; for (let n=0;n<N;n++){ const ang=n/N*2*Math.PI; let r=4; let prev=px(cx,cy);
    for(;r<200;r+=0.5){ const p=px(Math.round(cx+r*Math.cos(ang)),Math.round(cy+r*Math.sin(ang))); if(Math.abs(p[0]-ref[0])+Math.abs(p[1]-ref[1])+Math.abs(p[2]-ref[2])>th) break; } radii.push(r); }
  const sm=radii.map((_,i)=>{const w=[];for(let k=-3;k<=3;k++)w.push(radii[(i+k+N)%N]);return w.sort((a,b)=>a-b)[3];});
  return sm.map((r,i)=>{const a=i/N*2*Math.PI;return [cx+r*Math.cos(a),cy+r*Math.sin(a)];}); };
window.__trace = trace;
const S = 0.5, W = 240;
const dbg = document.createElement('canvas'); dbg.width = 3*W; dbg.height = W; dbg.id='dbg';
Object.assign(dbg.style,{position:'fixed',top:'0',left:'0',zIndex:9999,width:(3*W*S)+'px',height:(W*S)+'px'});
const g = dbg.getContext('2d');
[['top',975,367],['left',674,707],['right',1167,670]].forEach(([n,cx,cy],i)=>{
  g.save(); g.translate(i*W,0); g.drawImage(img,cx-W/2,cy-W/2,W,W,0,0,W,W);
  [[25,'#0f0'],[40,'#f0f'],[70,'#0ff']].forEach(([th,col])=>{ g.strokeStyle=col; g.beginPath(); trace(cx,cy,th).forEach(([X,Y],k)=>{X=X-cx+W/2;Y=Y-cy+W/2;k?g.lineTo(X,Y):g.moveTo(X,Y);}); g.closePath(); g.stroke(); });
  g.restore(); });
document.body.append(dbg); 'ok'

