const solve=(A,b)=>{const n=b.length;A=A.map((r,i)=>[...r,b[i]]);for(let i=0;i<n;i++){let m=i;for(let k=i+1;k<n;k++)if(Math.abs(A[k][i])>Math.abs(A[m][i]))m=k;[A[i],A[m]]=[A[m],A[i]];for(let k=i+1;k<n;k++){const f=A[k][i]/A[i][i];for(let j=i;j<=n;j++)A[k][j]-=f*A[i][j];}}const x=Array(n).fill(0);for(let i=n-1;i>=0;i--){let s=A[i][n];for(let j=i+1;j<n;j++)s-=A[i][j]*x[j];x[i]=s/A[i][i];}return x;};
const fit=(pts,ox,oy)=>{const M=Array.from({length:5},()=>Array(5).fill(0)),v=Array(5).fill(0);for(const [X,Y] of pts){const x=X-ox,y=Y-oy,r=[x*x,x*y,y*y,x,y];for(let i=0;i<5;i++){v[i]+=r[i];for(let j=0;j<5;j++)M[i][j]+=r[i]*r[j];}}const [a,b,c,d,e]=solve(M,v);
 const den=4*a*c-b*b;const x0=(b*e-2*c*d)/den,y0=(b*d-2*a*e)/den;const F=1+ (a*x0*x0+b*x0*y0+c*y0*y0) ; // value at center: a x0^2+... + d x0 + e y0 - 1 = -F'
 const k=1-(a*x0*x0+b*x0*y0+c*y0*y0+d*x0+e*y0); const th=0.5*Math.atan2(b,a-c); const ct=Math.cos(th),st=Math.sin(th);
 const A2=a*ct*ct+b*ct*st+c*st*st, C2=a*st*st-b*ct*st+c*ct*ct; return {cx:x0+ox,cy:y0+oy,rx:Math.sqrt(k/A2),ry:Math.sqrt(k/C2),deg:th*180/Math.PI};};
const resid=(E,[X,Y])=>{const t=-E.deg*Math.PI/180,x=X-E.cx,y=Y-E.cy,u=x*Math.cos(t)-y*Math.sin(t),w=x*Math.sin(t)+y*Math.cos(t);return Math.abs(Math.hypot(u/E.rx,w/E.ry)-1);};
const out={};
for (const [n,cx,cy,th] of [['top',975,367,40],['left',674,707,40],['right',1167,670,40]]) {
  let pts=window.__trace(cx,cy,th); let E=fit(pts,cx,cy);
  for(let it=0;it<3;it++){const rs=pts.map(p=>resid(E,p));const med=[...rs].sort((a,b)=>a-b)[rs.length>>1];pts=pts.filter((p,i)=>rs[i]<=Math.max(med*2,0.02));E=fit(pts,cx,cy);}
  out[n]=Object.fromEntries(Object.entries(E).map(([k,v])=>[k,+v.toFixed(1)])); out[n].kept=pts.length;
}
window.__ell=out; out

