  const i=Math.floor(X), j=Math.floor(Y), fx=X-i, fy=Y-j; const L=(a,b)=>{const k=(b*1920+a)*4; return 0.2126*d[k]+0.7152*d[k+1]+0.0722*d[k+2];};
  return L(i,j)*(1-fx)*(1-fy)+L(i+1,j)*fx*(1-fy)+L(i,j+1)*(1-fx)*fy+L(i+1,j+1)*fx*fy; };
const E={ top:[970.7,361.1,58.2,94.9,55.6], left:[669.8,697.7,43.6,105.4,59.1], right:[1169.1,675.6,37.8,70.2,-56.4] };
const res={};
for (const [n,[cx,cy,rx,ry,deg]] of Object.entries(E)) {
  const t=deg*Math.PI/180, N=180, pts=[];
  for (let k=0;k<N;k++){ const a=k/N*2*Math.PI; const ex=rx*Math.cos(a), ey=ry*Math.sin(a);
    const px=ex*Math.cos(t)-ey*Math.sin(t), py=ex*Math.sin(t)+ey*Math.cos(t); const R=Math.hypot(px,py), ux=px/R, uy=py/R;
    // profile along ray, search 0.7R..1.35R for strongest step (5px window)
    let best=-1, bestR=R;
