 const A2=a*ct*ct+b*ct*st+c*st*st,C2=a*st*st-b*ct*st+c*ct*ct;return [x0+ox,y0+oy,Math.sqrt(k/A2),Math.sqrt(k/C2),th*180/Math.PI];};
