const d=x.getImageData(0,0,1920,1080).data;
const lum=(X,Y)=>{const i=Math.floor(X),j=Math.floor(Y),fx=X-i,fy=Y-j;const L=(a,b)=>{const k=(b*1920+a)*4;return 0.2126*d[k]+0.7152*d[k+1]+0.0722*d[k+2];};return L(i,j)*(1-fx)*(1-fy)+L(i+1,j)*fx*(1-fy)+L(i,j+1)*(1-fx)*fy+L(i+1,j+1)*fx*fy;};
const step=(cx,cy,ux,uy,r)=>Math.abs((lum(cx+ux*(r+1.5),cy+uy*(r+1.5))+lum(cx+ux*(r+2.5),cy+uy*(r+2.5)))-(lum(cx+ux*(r-2.5),cy+uy*(r-2.5))+lum(cx+ux*(r-1.5),cy+uy*(r-1.5))))/2;
const N=240;
const trace=(cx,cy)=>{const R=[];for(let k=0;k<N;k++){const a=k/N*2*Math.PI,ux=Math.cos(a),uy=Math.sin(a);let r=12;for(;r<160;r+=0.5){if(step(cx,cy,ux,uy,r)>16)break;}let br=r,bs=0;for(let q=r;q<r+4;q+=0.25){const s=step(cx,cy,ux,uy,q);if(s>bs){bs=s;br=q;}}R.push(br);}
 const med=R.map((_,i)=>{const w=[];for(let k=-4;k<=4;k++)w.push(R[(i+k+N)%N]);return w.sort((a,b)=>a-b)[4];});
 return med.map((_,i)=>{let s=0;for(let k=-3;k<=3;k++)s+=med[(i+k+N)%N];return s/7;}); };
