const lc=left.reduce((s,p)=>[s[0]+p[0]/N,s[1]+p[1]/N],[0,0]); const L0=left.map(([X,Y])=>[X-lc[0],Y-lc[1]]);
window.__L0=L0; window.__midR=midR;
// radius of a polygon along ray from (cx,cy) at angle a
window.__polyRay=(P,cx,cy,a)=>{const ux=Math.cos(a),uy=Math.sin(a);let best=0;for(let i=0;i<P.length;i++){const [x1,y1]=P[i],[x2,y2]=P[(i+1)%P.length];const ex=x2-x1,ey=y2-y1,wx=x1-cx,wy=y1-cy;const den=ux*ey-uy*ex;if(Math.abs(den)<1e-9)continue;const t=(wx*ey-wy*ex)/den,s=(wx*uy-wy*ux)/den;if(t>0&&s>=0&&s<=1)best=Math.max(best,t);}return best;};
