const img = new Image(); img.src = '/assets/images/hero-lamps-1920.webp'; await img.decode();
document.getElementById('mark-tool')?.remove();
const cx=975, cy=362, W=260, Z=3, CSS=Math.min(innerWidth-20, 600);
const wrap=document.createElement('div'); wrap.id='mark-tool';
Object.assign(wrap.style,{position:'fixed',inset:'0',zIndex:99999,background:'#111',color:'#fff',font:'14px system-ui',padding:'10px',overflow:'auto'});
wrap.innerHTML='<p style="margin:0 0 8px">Kliknij kilka punktów, przez które ma przechodzić krawędź światła (czerwone kropki). <button id="mk-undo">Cofnij</button> <button id="mk-clear">Wyczyść</button> <button id="mk-done">Gotowe</button> <span id="mk-n">0 pkt</span></p>';
const cv=document.createElement('canvas'); cv.width=W*Z; cv.height=W*Z; Object.assign(cv.style,{width:CSS+'px',height:CSS+'px',cursor:'crosshair',display:'block'}); wrap.append(cv); document.body.append(wrap);
const path=new Path2D(document.querySelector('.hero__lamp--top .hero__lens path').getAttribute('d'));
window.__marks=[]; window.__markDone=false;
const draw=()=>{const g=cv.getContext('2d'); g.setTransform(1,0,0,1,0,0); g.clearRect(0,0,cv.width,cv.height); g.scale(Z,Z); g.drawImage(img,cx-W/2,cy-W/2,W,W,0,0,W,W);
  g.save(); g.translate(W/2-cx,W/2-cy); g.strokeStyle='#0ff'; g.lineWidth=0.5; g.stroke(path); g.restore();
  g.fillStyle='#f00'; window.__marks.forEach(([x,y])=>{g.beginPath(); g.arc(x-cx+W/2,y-cy+W/2,1.5,0,7); g.fill();}); document.getElementById('mk-n').textContent=window.__marks.length+' pkt';};
cv.addEventListener('click',e=>{const r=cv.getBoundingClientRect(); const x=(e.clientX-r.left)/r.width*W+cx-W/2, y=(e.clientY-r.top)/r.height*W+cy-W/2; window.__marks.push([+x.toFixed(1),+y.toFixed(1)]); draw();});
document.getElementById('mk-undo').onclick=()=>{window.__marks.pop();draw();};
document.getElementById('mk-clear').onclick=()=>{window.__marks=[];draw();};
document.getElementById('mk-done').onclick=()=>{window.__markDone=true; document.getElementById('mk-n').textContent=window.__marks.length+' pkt – zapisane, wróć do czatu';};
draw(); 'ready'

