await new Promise(r=>setTimeout(r,800));
const name = el => (el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') && document.getElementById(el.getAttribute('aria-labelledby'))?.textContent || el.textContent || el.querySelector('img')?.alt || el.title || '').trim();
const issues = [];
const heads = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h => [+h.tagName[1], h.textContent.trim().slice(0,40)]);
for (let i=1;i<heads.length;i++) if (heads[i][0] > heads[i-1][0]+1) issues.push('heading skip: '+heads[i-1][1]+' -> '+heads[i][1]);
if (document.querySelectorAll('h1').length!==1) issues.push('h1 count '+document.querySelectorAll('h1').length);
document.querySelectorAll('a,button,[role=switch]').forEach(el => { if (!name(el)) issues.push('no name: '+el.outerHTML.slice(0,90)); });
document.querySelectorAll('a').forEach(a => { if (!a.hasAttribute('href')) issues.push('a without href: '+a.outerHTML.slice(0,80)); });
const imgs=[...document.querySelectorAll('img')]; imgs.forEach(i => { if (!i.hasAttribute('alt')) issues.push('img no alt '+i.src); if (!i.getAttribute('width')||!i.getAttribute('height')) issues.push('img no size '+i.src.split('/').pop()); const top=i.getBoundingClientRect().top+scrollY; if (top>innerHeight*1.2 && i.loading!=='lazy') issues.push('below fold not lazy '+i.src.split('/').pop()); });
document.querySelectorAll('section').forEach(s => { if (!s.getAttribute('aria-labelledby') && !s.getAttribute('aria-label') && !s.querySelector('h1,h2,h3')) issues.push('section without heading '+s.className); });
document.querySelectorAll('[aria-controls]').forEach(e=>{ if(!document.getElementById(e.getAttribute('aria-controls'))) issues.push('aria-controls broken '+e.getAttribute('aria-controls')); });
document.querySelectorAll('[aria-labelledby]').forEach(e=>{ e.getAttribute('aria-labelledby').split(' ').forEach(id=>{ if(!document.getElementById(id)) issues.push('labelledby broken '+id); }); });
const ids={}; document.querySelectorAll('[id]').forEach(e=>{ids[e.id]=(ids[e.id]||0)+1}); Object.entries(ids).forEach(([k,v])=>{ if(v>1) issues.push('dup id '+k); });
document.querySelectorAll('[onclick], div[tabindex], span[tabindex]').forEach(e=>issues.push('div/span interactive '+e.outerHTML.slice(0,60)));
({ lang: document.documentElement.lang, landmarks: ['header','nav','main','footer'].map(t=>t+':'+document.querySelectorAll(t).length), headings: heads, imgs: imgs.length, issues })

